  {"questionId": "B4-U6-Q019", "term": "Logical Security", "definition": "A group of software safeguards for organization systems, including user identification, password access, and authentication."},
  {"questionId": "B4-U6-Q020", "term": "Account", "definition": "A set of credentials that identifies an individual within a network and is needed to reach shared folders, printers, and applications."},
  {"questionId": "B4-U6-Q021", "term": "Administrator Account", "definition": "An account that allows changes affecting other users and carries full rights and permissions to all network resources."},
  {"questionId": "B4-U6-Q022", "term": "User Account", "definition": "A record that represents one person and stores the username and password or Personal Identification Number (PIN) used for logon authentication."},
  {"questionId": "B4-U6-Q023", "term": "Security Identifier", "definition": "A unique value that names a user account internally and is used to track rights and permission assignments."},
  {"questionId": "B4-U6-Q025", "term": "Guest Account", "definition": "A built-in local account that lets people log on or reach resources without a unique local username; policies usually disable it."},
  {"questionId": "B4-U6-Q026", "term": "Domain User Account", "definition": "An account created in Active Directory (AD), stored in Organizational Units (OUs), and replicated so a person can log in on any valid computer."},
  {"questionId": "B4-U6-Q027", "term": "Discretionary Access Control List", "definition": "A structure attached to an object in Microsoft systems that implements permissions, such as read only for a given user."},
  {"questionId": "B4-U6-Q028", "term": "Rights", "definition": "An authority given to a user account or group to perform predefined tasks, such as logging into a computer or creating accounts."},
  {"questionId": "B4-U6-Q029", "term": "Group Policy Object", "definition": "A collection of settings that defines how a system looks and behaves for a defined group of users in Active Directory (AD)."},
  {"questionId": "B4-U6-Q030", "term": "Security Technical Implementation Guide", "definition": "A configuration standard of cybersecurity requirements for one specific product, with technical guidance to lock down systems and software."},
  {"questionId": "B4-U7-Q014", "term": "Application Services", "definition": "A software solution that improves the speed, security, and operability of programs while running quietly in the background."},
  {"questionId": "B4-U7-Q015", "term": "Daemon", "definition": "A background utility program in Linux that monitors and takes care of a subsystem without any controlling terminal."},
  {"questionId": "B4-U7-Q016", "term": "Windows Task Manager", "definition": "A utility that gives a bird's-eye view of what is going on with a system and shows its running services."},
  {"questionId": "B4-U7-Q017", "term": "Active Directory (AD) Service", "definition": "A service Microsoft developed for Windows networks that oversees centralized domain management and identity-related functions."},
  {"questionId": "B4-U7-Q018", "term": "Prefetch and Superfetch Service", "definition": "A Windows component that preloads frequently used files and apps into Random Access Memory (RAM) so the slower hard disk is needed less often."},
  {"questionId": "B4-U7-Q019", "term": "Background Intelligent Transfer Service (BITS)", "definition": "A Windows component that moves files between machines over idle bandwidth and delivers software updates from servers to clients."},
  {"questionId": "B4-U7-Q020", "term": "Domain Name System (DNS) Client Service", "definition": "A Windows component that turns domain names into addresses and remembers the answers in a local cache."},
  {"questionId": "B4-U7-Q021", "term": "Computer Browser Service", "definition": "A Windows component that helps users find shared resources on neighboring computers by collecting all the information on one computer."},
  {"questionId": "B4-U7-Q022", "term": "Service Control Manager (SCM)", "definition": "A component that manages Windows services and keeps a database of how each one should be started."},
  {"questionId": "B4-U7-Q023", "term": "Services Tab", "definition": "A Task Manager view that lists all current Windows 10 background programs and links to start, stop, and restart them."},
  {"questionId": "B4-U7-Q024", "term": "Services Snap-In", "definition": "A tool built upon the Microsoft Management Console (MMC) that lets administrators observe, start, stop, and restart Windows services."},
  {"questionId": "B4-U8-Q012", "term": "Process", "definition": "A program developed for the end user that is executing, such as the action that happens when an application is clicked."},
  {"questionId": "B4-U8-Q014", "term": "Command Shell", "definition": "The first Windows command-line shell, built in to automate routine tasks such as nightly backups with batch files."},
  {"questionId": "B4-U8-Q015", "term": "PowerShell", "definition": "A Windows command-line shell that extends the Command shell and runs commands called cmdlets with a more extensible scripting language."},
  {"questionId": "B4-U8-Q016", "term": "Work Process", "definition": "A server component that carries out the actual tasks by activating, generating, and executing them and monitoring them until finished."},
  {"questionId": "B4-U8-Q017", "term": "Primary Work Process", "definition": "A work process used for special central tasks that must not be allocated, such as time basis and process administration."},
  {"questionId": "B4-U8-Q018", "term": "Communication Process", "definition": "A type of server process that holds the connections to the agents and user interfaces."},
  {"questionId": "B4-U8-Q019", "term": "Processes Tab", "definition": "A Task Manager view that breaks down how everything on the system is performing and how resources are being used."}
